CREATE OR REPLACE FUNCTION gf_delete_account() RETURNS json LANGUAGE sql SECURITY DEFINER SET search_path = public AS $body$ WITH del_devices AS (DELETE FROM devices WHERE user_id = auth.uid() RETURNING 1), del_consents AS (DELETE FROM consent_records WHERE user_id = auth.uid() RETURNING 1), upd AS (UPDATE users SET identity_id = 'deleted:' || gen_random_uuid()::text, nickname = NULL, avatar_url = NULL, status = 'DELETED', updated_at = now() WHERE identity_id = auth.uid() AND status <> 'DELETED' RETURNING updated_at) SELECT json_build_object('status', CASE WHEN (SELECT count(*) FROM upd) > 0 THEN 'DELETED' ELSE 'NOT_FOUND' END, 'deletedDevices', (SELECT count(*) FROM del_devices), 'deletedConsents', (SELECT count(*) FROM del_consents), 'deletedAt', (SELECT updated_at FROM upd)) $body$;